export const ITEM_TEMPLATES={potion:{name:'Potion',effects:[{kind:'restore',resource:'HP',amountMode:'flat',amount:20,target:'single',context:'both'}],itemType:'consumable',reusable:false},ether:{name:'Ether',effects:[{kind:'restore',resource:'PP',amountMode:'flat',amount:10,target:'single',context:'both'}],itemType:'consumable',reusable:false},revive:{name:'Revive',effects:[{kind:'revive',resource:'HP',amountMode:'percent',amount:50,target:'single',context:'both'}],itemType:'consumable',reusable:false},max_revive:{name:'Max Revive',effects:[{kind:'revive',resource:'HP',amountMode:'percent',amount:100,target:'single',context:'both'}],itemType:'consumable',reusable:false},tm:{name:'TM',effects:[{kind:'teach',moveId:343}],itemType:'tm',reusable:false},hm:{name:'HM',effects:[{kind:'teach',moveId:343}],itemType:'hm',reusable:true}};
export const ABILITY_TEMPLATES={fluffy:{name:'Fluffy',rules:[{when:'damage_calculation',condition:'contact',effect:'damage_multiplier',value:50,parameter:'incoming',target:'self'},{when:'damage_calculation',condition:'fire',effect:'damage_multiplier',value:200,parameter:'incoming',target:'self'}]},fluffy_all_fire:{name:'Fluffy · all Fire vulnerability',rules:[{when:'damage_calculation',condition:'contact_non_fire',effect:'damage_multiplier',value:50,parameter:'incoming',target:'self'},{when:'damage_calculation',condition:'fire',effect:'damage_multiplier',value:200,parameter:'incoming',target:'self'}]},intimidate:{name:'Intimidate',rules:[{when:'switch_in',condition:'always',effect:'stat_stage',value:-1,parameter:'Attack',target:'enemy'}]},drought:{name:'Drought',rules:[{when:'switch_in',condition:'always',effect:'weather',value:5,parameter:'bright_sunlight',target:'field'}]},sand_stream:{name:'Sand Stream',rules:[{when:'switch_in',condition:'always',effect:'weather',value:5,parameter:'sandstorm',target:'field'}]},rain_dish:{name:'Rain Dish',rules:[{when:'turn_end',condition:'weather',effect:'heal_percent',value:6.25,parameter:'rain',target:'self'}]},crystal_body:{name:'Crystal Body',rules:[{when:'damage_calculation',condition:'contact_non_fire',effect:'damage_multiplier',value:50,parameter:'incoming',target:'self'},{when:'damage_calculation',condition:'fire',effect:'damage_multiplier',value:200,parameter:'incoming',target:'self'},{when:'damage_calculation',condition:'water',effect:'damage_multiplier',value:0,parameter:'incoming',target:'self'}]}};
export function previewDamageRules(rules,{contact=false,type='normal'}={}){let multiplier=1;for(const r of rules){if(r.target&&r.target!=='self')continue;if(!['damage_calculation','always'].includes(r.when)||r.effect!=='damage_multiplier'||r.parameter!=='incoming')continue;const match=r.condition==='always'||r.condition==='contact'&&contact||r.condition==='non_contact'&&!contact||r.condition==='contact_non_fire'&&contact&&type!=='fire'||r.condition==='fire'&&type==='fire'||r.condition==='water'&&type==='water';if(match)multiplier*=r.value/100;}return multiplier;}
export function validateItemRecipe(recipe){if(!recipe||!['held','hm','tm','consumable','key'].includes(recipe.itemType)||typeof recipe.reusable!=='boolean'||!Array.isArray(recipe.effects)||recipe.effects.length>32)throw Error('Invalid item recipe.');for(const e of recipe.effects){if(!['restore','revive','teach','change_ability','buff','status'].includes(e.kind))throw Error('Unknown item effect.');if(['restore','revive'].includes(e.kind)){if(!['HP','PP'].includes(e.resource)||!['flat','percent'].includes(e.amountMode)||!Number.isFinite(e.amount)||e.amount<1||e.amount>(e.amountMode==='percent'?100:65535)||!['single','party'].includes(e.target)||!['battle','overworld','both'].includes(e.context))throw Error('Invalid restoration settings.');}if(e.kind==='teach'&&(!Number.isInteger(e.moveId)||e.moveId<1||e.moveId>65535))throw Error('Choose a valid move ID.');}return recipe;}
